from flask import Flask, render_template_string, request, session, redirect, url_for
import sqlite3
import os
import datetime
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.secret_key = os.environ.get("SECRET_KEY") or os.urandom(32)
app.config["SESSION_COOKIE_HTTPONLY"] = True
app.config["SESSION_COOKIE_SAMESITE"] = "Lax"
DB_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "it_service_system.db")

# ==============================================
# DATABASE CONNECTION
# ==============================================
def get_db():
    try:
        conn = sqlite3.connect(DB_FILE)
        conn.row_factory = sqlite3.Row
        return conn
    except Exception as e:
        print(f"DB Error: {e}")
        return None

# ==============================================
# CREATE TABLES
# ==============================================
def init_db():
    conn = get_db()
    if not conn: return
    cur = conn.cursor()

    cur.execute("""
    CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        full_name TEXT NOT NULL,
        email TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'requestor',
        department TEXT,
        contact_number TEXT,
        is_active INTEGER DEFAULT 1,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )""")

    cur.execute("""
    CREATE TABLE IF NOT EXISTS tickets (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        reference_no TEXT UNIQUE NOT NULL,
        requestor_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        department TEXT NOT NULL,
        contact_number TEXT NOT NULL,
        equipment_type TEXT NOT NULL,
        brand_model TEXT,
        serial_property_no TEXT,
        location_room TEXT NOT NULL,
        problem_description TEXT NOT NULL,
        priority TEXT NOT NULL DEFAULT 'medium',
        status TEXT NOT NULL DEFAULT 'pending_admin',
        assigned_to INTEGER REFERENCES users(id) ON DELETE SET NULL,
        scheduled_date TEXT,
        work_done TEXT,
        parts_replaced TEXT,
        resolution_notes TEXT,
        requestor_feedback TEXT,
        admin_approved INTEGER DEFAULT 0,
        staff_approved INTEGER DEFAULT 0,
        submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        completed_at TIMESTAMP,
        approved_at TIMESTAMP
    )""")

    cur.execute("""
    CREATE TABLE IF NOT EXISTS status_history (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        ticket_id INTEGER NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
        status TEXT NOT NULL,
        notes TEXT,
        updated_by INTEGER NOT NULL REFERENCES users(id),
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )""")

    cur.execute("""
    CREATE TABLE IF NOT EXISTS notifications (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        ticket_id INTEGER REFERENCES tickets(id) ON DELETE CASCADE,
        message TEXT NOT NULL,
        is_read INTEGER DEFAULT 0,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )""")

    conn.commit()
    conn.close()

init_db()

# ==============================================
# PHILIPPINE TIME — UTC+8
# ==============================================
def ph_now():
    return datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8)))

# ==============================================
# REFERENCE NUMBER: REQ-2026-00001
# ==============================================
def generate_ref_no():
    now = ph_now()
    year = now.year
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT COUNT(*) FROM tickets WHERE strftime('%Y', submitted_at) = ?", (str(year),))
    count = cur.fetchone()[0] + 1
    conn.close()
    return f"REQ-{year}-{count:05d}"

# ==============================================
# DECORATORS
# ==============================================
def login_required(f):
    from functools import wraps
    @wraps(f)
    def wrap(*args, **kwargs):
        if 'user_id' not in session:
            return redirect(url_for('login'))
        return f(*args, **kwargs)
    return wrap

def staff_required(f):
    from functools import wraps
    @wraps(f)
    def wrap(*args, **kwargs):
        if 'user_id' not in session:
            return redirect(url_for('login'))
        if session.get('role') != 'staff':
            return " Access Denied — IT Staff Only", 403
        return f(*args, **kwargs)
    return wrap

def admin_required(f):
    from functools import wraps
    @wraps(f)
    def wrap(*args, **kwargs):
        if 'user_id' not in session:
            return redirect(url_for('login'))
        if session.get('role') != 'admin':
            return " Access Denied — Admin Only", 403
        return f(*args, **kwargs)
    return wrap

# ==============================================
# ROUTES
# ==============================================
