@app.route('/dashboard')
@login_required
def dashboard():
    conn = get_db()
    cur = conn.cursor()
    role = session.get('role')
    user_id = session['user_id']

    if role == 'requestor':
        cur.execute("""
            SELECT id, reference_no, equipment_type, status, priority, submitted_at
            FROM tickets WHERE requestor_id = ? ORDER BY submitted_at DESC
        """, (user_id,))
        tickets = cur.fetchall()

    elif role == 'admin':
        cur.execute("""
            SELECT t.id, t.reference_no, t.equipment_type, t.department, t.status,
                    t.priority, t.submitted_at, u.full_name as requestor_name,
                   ass.full_name as assigned_name, t.scheduled_date, t.admin_approved, t.staff_approved
            FROM tickets t
            JOIN users u ON t.requestor_id = u.id
            LEFT JOIN users ass ON t.assigned_to = ass.id
            ORDER BY t.submitted_at DESC
        """)
        tickets = cur.fetchall()

    else:
        cur.execute("""
            SELECT t.id, t.reference_no, t.equipment_type, t.department, t.status,
                    t.priority, t.submitted_at, u.full_name as requestor_name,
                   t.scheduled_date, t.work_done, t.parts_replaced
            FROM tickets t
            JOIN users u ON t.requestor_id = u.id
            WHERE t.assigned_to = ? ORDER BY t.submitted_at DESC
        """, (user_id,))
        tickets = cur.fetchall()

    cur.execute("SELECT COUNT(*) FROM notifications WHERE user_id = ? AND is_read = 0", (user_id,))
    notif_count = cur.fetchone()[0]

    conn.close()

    welcome_msg = {
        'admin': " Welcome, Admin! Review requests, assign to Staff, and approve completed work.",
        'staff': " Welcome, Staff! See tasks assigned to you. Set schedule, report work done, then approve.",
        'requestor': " Welcome! Submit repair requests, track status, and give feedback once fixed."
    }.get(role, "Welcome!")

    return render_template_string(BASE_TEMPLATE,
        welcome_msg=welcome_msg,
        tickets=tickets,
        notif_count=notif_count,
        role=role)

